-- Catálogo bilíngue 10/10, parte 1/4 (500 palavras). Execute as quatro partes em ordem.
-- Reexecutável: atualiza definition_pt e example_pt de palavras já importadas.
begin;
do $$ begin if exists (select 1 from (select unnest(array['arts', 'business', 'food', 'general-vocabulary', 'health', 'law', 'politics', 'science', 'sports', 'technical', 'technology']) as slug) required left join public.vocabulary_categories c using (slug) where c.id is null) then raise exception 'Categorias do catálogo ausentes'; end if; end $$;
insert into public.vocabulary_words (word,translation,definition_en,definition_pt,example_en,example_pt,cefr_level,word_type,category_id,frequency_rank)
select v.word,v.translation,v.definition_en,v.definition_pt,v.example_en,v.example_pt,v.cefr_level,v.word_type,c.id,v.frequency_rank
from jsonb_to_recordset($catalog$
[
{"word":"dugong","translation":"dugongo","definition_en":"A large, herbivorous marine mammal with a rounded body, flippers, and a forked tail, found in warm coastal waters from East Africa to Australia.","definition_pt":"Um mamífero marinho grande e herbívoro com um corpo arredondado, nadadeiras e uma cauda bifurcada, encontrado em águas costeiras quentes da África Oriental à Austrália.","example_en":"The dugong is often called a sea cow because it grazes on seagrass.","example_pt":"O dugong é muitas vezes chamado de vaca marinha porque pasta em grama.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"dulcimer","translation":"saltério","definition_en":"A stringed musical instrument played by striking the strings with small hammers or by plucking.","definition_pt":"Um instrumento musical com cordas tocado por golpear as cordas com pequenos martelos ou por arrancar.","example_en":"She played a beautiful melody on the dulcimer.","example_pt":"Ela tocou uma melodia linda no dulcimer.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"dunghill","translation":"estrumeira","definition_en":"A pile of animal excrement, manure, or other waste material, often found on a farm.","definition_pt":"Uma pilha de excrementos de animais, estrume, ou outros resíduos, encontrados em uma fazenda.","example_en":"The farmer cleared the dunghill from the barnyard.","example_pt":"O fazendeiro limpou o esterco do celeiro.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"duodecimal","translation":"duodecimal","definition_en":"Relating to a number system that uses twelve as its base, rather than ten.","definition_pt":"Relativo a um sistema de números que usa doze como base, ao invés de dez.","example_en":"The duodecimal system is sometimes used in measurements like inches and feet.","example_pt":"O sistema duodecimal é usado em medidas como centímetros e pés.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"duodenal","translation":"duodenal","definition_en":"In or relating to the duodenum, which is the first part of the small intestine.","definition_pt":"No duodeno, que é a primeira parte do intestino delgado.","example_en":"The patient was diagnosed with a duodenal ulcer.","example_pt":"O paciente foi diagnosticado com úlcera duodenal.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"duodenum","translation":"duodeno","definition_en":"The initial section of the small intestine, located between the stomach and the jejunum, where most chemical digestion occurs.","definition_pt":"A seção inicial do intestino delgado, localizada entre o estômago e o jejuno, onde ocorre a maior parte da digestão química.","example_en":"The duodenum receives chyme from the stomach and digestive enzymes from the pancreas.","example_pt":"O duodeno recebe quime do estômago e enzimas digestivas do pâncreas.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"duplication","translation":"duplicação","definition_en":"A copy that corresponds to an original exactly.","definition_pt":"Uma cópia que corresponde exatamente a um original.","example_en":"The duplication of the key was perfect.","example_pt":"A duplicação da chave foi perfeita.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"durability","translation":"durabilidade","definition_en":"The ability of a material or item to remain intact and functional over time despite stress or force.","definition_pt":"A habilidade de um material ou item permanecer intacto e funcional ao longo do tempo, apesar do estresse ou força.","example_en":"The durability of this phone is impressive; it survived multiple drops.","example_pt":"A durabilidade deste telefone é impressionante, sobreviveu a várias gotas.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"duty-free","translation":"duty-free","definition_en":"Goods that are sold without the addition of customs or import taxes, typically in airports or international zones.","definition_pt":"Mercadorias vendidas sem a adição de impostos aduaneiros ou de importação, tipicamente em aeroportos ou zonas internacionais.","example_en":"She bought perfume at the duty-free shop in the airport.","example_pt":"Ela comprou perfume na loja de duty-free no aeroporto.","cefr_level":"B1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"dwarfism","translation":"nanismo","definition_en":"A genetic or medical condition characterized by abnormally short stature, often due to growth hormone deficiencies or skeletal dysplasias.","definition_pt":"Uma doença genética ou médica caracterizada por baixa estatura, muitas vezes devido a deficiências de hormônio do crescimento ou displasias esqueléticas.","example_en":"Achondroplasia is the most common form of dwarfism.","example_pt":"Acondroplasia é a forma mais comum de nanismo.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dwindle","translation":"diminuir","definition_en":"To become gradually less or smaller over time.","definition_pt":"Tornar-se gradualmente menor ou menor com o tempo.","example_en":"The population of the village dwindled after the factory closed.","example_pt":"A população da aldeia diminuiu depois que a fábrica fechou.","cefr_level":"B2","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"dyadic","translation":"diádico","definition_en":"Pertaining to or consisting of two parts, elements, or individuals; based on a dyad.","definition_pt":"Pertencia a ou consistia em duas partes, elementos, ou indivíduos, baseado em uma díade.","example_en":"The dyadic relationship between the two partners was central to the study.","example_pt":"A relação diadica entre os dois parceiros era central para o estudo.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"dynamically","translation":"dinamicamente","definition_en":"In a way that involves constant change, activity, or progress.","definition_pt":"De uma forma que envolve mudança constante, atividade ou progresso.","example_en":"The market is dynamically evolving with new technologies.","example_pt":"O mercado está evoluindo dinamicamente com novas tecnologias.","cefr_level":"C1","word_type":"adverb","category_slug":"technology","frequency_rank":null},
{"word":"dynast","translation":"dinasta","definition_en":"A ruler who belongs to a family or line of hereditary rulers, often holding power through succession.","definition_pt":"Um governante que pertence a uma família ou linhagem de governantes hereditários, muitas vezes mantendo o poder através da sucessão.","example_en":"The ancient dynast ruled the kingdom for over forty years.","example_pt":"O antigo dinast governou o reino por mais de quarenta anos.","cefr_level":"C1","word_type":"noun","category_slug":"politics","frequency_rank":null},
{"word":"dynastic","translation":"dinástico","definition_en":"Pertaining to a sequence of rulers from the same family or line.","definition_pt":"Pertencia a uma sequência de governantes da mesma família ou linhagem.","example_en":"The dynastic struggles of the 15th century shaped modern Europe.","example_pt":"As lutas dinásticas do século XV moldaram a Europa moderna.","cefr_level":"C1","word_type":"adjective","category_slug":"politics","frequency_rank":null},
{"word":"dysarthria","translation":"disartria","definition_en":"A motor speech disorder resulting from neurological injury or damage to the peripheral motor nerves or speech muscles, causing difficulty in articulating words.","definition_pt":"Um distúrbio de fala motor resultante de lesão neurológica ou dano nos nervos motores periféricos ou músculos da fala, causando dificuldade em articular palavras.","example_en":"The patient was diagnosed with dysarthria after the stroke.","example_pt":"O paciente foi diagnosticado com disartria após o derrame.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dyscalculia","translation":"discalculia","definition_en":"A specific learning disability that affects a person's ability to understand numbers, learn math facts, and perform calculations.","definition_pt":"Uma deficiência específica de aprendizagem que afeta a capacidade de uma pessoa de entender números, aprender fatos matemáticos e realizar cálculos.","example_en":"Children with dyscalculia often struggle with basic arithmetic.","example_pt":"Crianças com discalculia muitas vezes lutam com aritmética básica.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dysgraphia","translation":"disgrafia","definition_en":"A neurological condition characterized by impaired ability to learn and produce written language, often affecting handwriting, spelling, and organizing thoughts on paper.","definition_pt":"Uma condição neurológica caracterizada por deficiência na habilidade de aprender e produzir linguagem escrita, afetando muitas vezes a escrita, ortografia e organizando pensamentos no papel.","example_en":"The student with dysgraphia uses a laptop to type assignments instead of writing by hand.","example_pt":"O aluno com disgrafia usa um laptop para digitar tarefas em vez de escrever à mão.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dyskinesia","translation":"discinesia","definition_en":"An abnormality in performing voluntary muscle movements, often characterized by involuntary or uncontrolled motions.","definition_pt":"Uma anormalidade na realização de movimentos musculares voluntários, muitas vezes caracterizados por movimentos involuntários ou descontrolados.","example_en":"The patient's dyskinesia made it difficult to perform simple tasks like writing.","example_pt":"A discinesia do paciente dificultou a realização de tarefas simples como escrever.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dysmenorrhea","translation":"dismenorreia","definition_en":"A medical condition characterized by severe and frequent menstrual cramps and pain during menstruation.","definition_pt":"Uma doença caracterizada por cólicas menstruais graves e frequentes e dor durante a menstruação.","example_en":"Many women experience dysmenorrhea during their menstrual cycle.","example_pt":"Muitas mulheres experimentam dismenorreia durante o ciclo menstrual.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dyspepsia","translation":"dispepsia","definition_en":"A condition of impaired digestion, often causing discomfort, bloating, or pain in the upper abdomen.","definition_pt":"Uma condição de digestão prejudicada, causando desconforto, inchaço ou dor no abdômen superior.","example_en":"The patient complained of dyspepsia after eating spicy food.","example_pt":"O paciente reclamou de dispepsia depois de comer comida picante.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dyspeptic","translation":"dispéptico","definition_en":"Relating to or suffering from dyspepsia, a condition of impaired digestion.","definition_pt":"Relacionado ou sofrendo de dispepsia, uma condição de digestão prejudicada.","example_en":"The dyspeptic patient complained of stomach pain after every meal.","example_pt":"O paciente dispéptico reclamou de dor de estômago depois de cada refeição.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"dysphagia","translation":"disfagia","definition_en":"A medical condition characterized by difficulty or pain when swallowing food, liquids, or saliva.","definition_pt":"Uma condição médica caracterizada por dificuldade ou dor ao engolir alimentos, líquidos ou saliva.","example_en":"The patient was diagnosed with dysphagia after complaining of pain while eating.","example_pt":"O paciente foi diagnosticado com disfagia após queixar-se de dor enquanto comia.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dysphasia","translation":"disfasia","definition_en":"A language disorder that affects a person's ability to produce or understand spoken or written language, typically resulting from brain damage.","definition_pt":"Uma desordem de linguagem que afeta a capacidade de uma pessoa de produzir ou entender a linguagem falada ou escrita, tipicamente resultante de danos cerebrais.","example_en":"The patient was diagnosed with dysphasia after the stroke.","example_pt":"O paciente foi diagnosticado com disfasia após o derrame.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dysphemism","translation":"disfemismo","definition_en":"A deliberately harsh, offensive, or disparaging word or phrase used in place of a neutral or polite one.","definition_pt":"Uma palavra ou frase deliberadamente dura, ofensiva ou depreciativa usada no lugar de uma neutra ou educada.","example_en":"Calling a hospital a 'meat wagon' is a crude dysphemism.","example_pt":"Chamar um hospital de \"carruagem de carne\" é um disfemismo grosseiro.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"dysphoria","translation":"disforia","definition_en":"A state of unease, dissatisfaction, or general unhappiness, often associated with mental health conditions.","definition_pt":"Um estado de desconforto, insatisfação ou infelicidade geral, muitas vezes associado a condições de saúde mental.","example_en":"The patient experienced severe dysphoria after the traumatic event.","example_pt":"O paciente sofreu disforia grave após o evento traumático.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dysphoric","translation":"disfórico","definition_en":"A state of intense emotional discomfort, dissatisfaction, or anxiety, often without a specific cause.","definition_pt":"Um estado de intenso desconforto emocional, insatisfação ou ansiedade, muitas vezes sem uma causa específica.","example_en":"The patient described feeling deeply dysphoric after the treatment changes.","example_pt":"O paciente descreveu sentir-se profundamente disfórico após as mudanças de tratamento.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"dysplasia","translation":"displasia","definition_en":"An abnormal growth or development of cells or tissues, often considered a condition that can sometimes progress to cancer.","definition_pt":"Um crescimento anormal ou desenvolvimento de células ou tecidos, muitas vezes considerado uma condição que pode às vezes evoluir para câncer.","example_en":"The biopsy revealed cervical dysplasia, which requires further monitoring.","example_pt":"A biópsia revelou displasia cervical, o que requer monitoramento.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dyspnea","translation":"dispneia","definition_en":"A medical condition characterized by labored or difficult respiration, often described as shortness of breath.","definition_pt":"Uma condição médica caracterizada por respiração difícil ou difícil, muitas vezes descrita como falta de ar.","example_en":"The patient experienced severe dyspnea after climbing the stairs.","example_pt":"O paciente sentiu dispneia grave após subir as escadas.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"dysprosium","translation":"disprósio","definition_en":"A trivalent metallic element of the rare earth group that forms highly magnetic compounds.","definition_pt":"Um elemento metálico trivalente do grupo Terra Rara que forma compostos altamente magnéticos.","example_en":"Dysprosium is used in the production of high-strength permanent magnets.","example_pt":"O disprósio é usado na produção de ímãs permanentes de alta resistência.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"dystopia","translation":"distopia","definition_en":"An imagined society or state where living conditions are extremely poor due to widespread deprivation, oppression, or terror.","definition_pt":"Uma sociedade imaginária ou estado onde as condições de vida são extremamente pobres devido à privação generalizada, opressão, ou terror.","example_en":"The novel depicts a dystopia where citizens are constantly monitored by the government.","example_pt":"O romance retrata uma distopia onde os cidadãos são constantemente monitorados pelo governo.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"dystopian","translation":"distópico","definition_en":"Describing a society or place that is extremely unpleasant, oppressive, or frightening, often imagined in fiction.","definition_pt":"Descrever uma sociedade ou lugar que é extremamente desagradável, opressivo ou assustador, muitas vezes imaginado na ficção.","example_en":"The novel paints a dystopian picture of a future ruled by a totalitarian regime.","example_pt":"O romance pinta um quadro distópico de um futuro governado por um regime totalitário.","cefr_level":"B2","word_type":"adjective","category_slug":"politics","frequency_rank":null},
{"word":"dystrophy","translation":"distrofia","definition_en":"A hereditary condition causing progressive weakness and loss of muscle mass.","definition_pt":"Uma condição hereditária causando fraqueza progressiva e perda de massa muscular.","example_en":"He was diagnosed with muscular dystrophy at a young age.","example_pt":"Ele foi diagnosticado com distrofia muscular em uma idade jovem.","cefr_level":"B2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"e-commerce","translation":"comércio eletrônico","definition_en":"The buying and selling of goods or services using the internet, and the transfer of money and data to execute these transactions.","definition_pt":"A compra e venda de bens ou serviços usando a internet, e a transferência de dinheiro e dados para executar essas transações.","example_en":"Many traditional stores have expanded into e-commerce to reach more customers.","example_pt":"Muitas lojas tradicionais se expandiram para o comércio eletrônico para alcançar mais clientes.","cefr_level":"B1","word_type":"noun","category_slug":"technology","frequency_rank":null},
{"word":"eaglet","translation":"filhote de águia","definition_en":"A juvenile or baby eagle, typically one that has not yet fully developed its adult plumage.","definition_pt":"Uma águia juvenil ou bebê, tipicamente uma que ainda não desenvolveu completamente sua plumagem adulta.","example_en":"The eaglet was learning to fly from its nest on the cliff.","example_pt":"A águia estava aprendendo a voar de seu ninho no penhasco.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"earache","translation":"otalgia","definition_en":"A continuous or sharp pain located in the middle or inner ear, often caused by infection or inflammation.","definition_pt":"Uma dor contínua ou aguda localizada no ouvido médio ou interno, muitas vezes causada por infecção ou inflamação.","example_en":"The child was crying because of a severe earache.","example_pt":"A criança estava chorando por causa de uma dor de ouvido grave.","cefr_level":"B1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"eared","translation":"orelhudo","definition_en":"Possessing ears or structures that resemble ears, often used in combination with another word.","definition_pt":"Possuindo orelhas ou estruturas que se assemelham a orelhas, muitas vezes usadas em combinação com outra palavra.","example_en":"The dog-eared pages of the book showed it was well-loved.","example_pt":"As páginas do livro mostram que era bem amada.","cefr_level":"B2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"earphone","translation":"fone de ouvido","definition_en":"An electro-acoustic transducer worn over or inserted into the ear to convert electrical signals into sound.","definition_pt":"Um transdutor eletro-acústico usado ou inserido na orelha para converter sinais elétricos em som.","example_en":"She put on her earphones to listen to music on the bus.","example_pt":"Ela colocou os fones de ouvido para ouvir música no ônibus.","cefr_level":"A2","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"earthenware","translation":"cerâmica","definition_en":"Pottery or dishes made from a porous clay that is fired at a relatively low temperature, often glazed to make it waterproof.","definition_pt":"Cerâmica ou pratos feitos de uma argila porosa que é disparada a uma temperatura relativamente baixa, muitas vezes vidradas para torná-lo à prova d'água.","example_en":"The museum displayed ancient earthenware from the Roman period.","example_pt":"O museu exibia louças antigas do período romano.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"earwax","translation":"cera de ouvido","definition_en":"A soft, yellowish substance produced by glands inside the ear canal, which helps protect and clean the ear.","definition_pt":"Uma substância suave e amarelada produzida por glândulas dentro do canal auditivo, que ajuda a proteger e limpar o ouvido.","example_en":"The doctor used a special tool to remove excess earwax.","example_pt":"O médico usou uma ferramenta especial para remover o excesso de cera.","cefr_level":"A2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"easement","translation":"servidão","definition_en":"A legal right to use another person's land for a specific purpose, such as a path or driveway, without owning it.","definition_pt":"Um direito legal de usar a terra de outra pessoa para um propósito específico, como um caminho ou entrada, sem possuí-la.","example_en":"The farmer granted an easement to the neighbor for access to the river.","example_pt":"O fazendeiro concedeu uma facilidade ao vizinho para o acesso ao rio.","cefr_level":"C1","word_type":"noun","category_slug":"law","frequency_rank":null},
{"word":"easterner","translation":"oriental","definition_en":"A person who lives in or comes from an eastern area, especially the eastern part of the United States.","definition_pt":"Uma pessoa que vive ou vem de uma área oriental, especialmente a parte oriental dos Estados Unidos.","example_en":"The easterner was surprised by the vast open spaces of the West.","example_pt":"O leste ficou surpreso com os vastos espaços abertos do Ocidente.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"ebonite","translation":"ebonite","definition_en":"A hard, non-resilient, black or dark-colored rubber produced by vulcanizing natural rubber with a high proportion of sulfur, often used for electrical insulation, combs, and buttons.","definition_pt":"Uma borracha dura, não resistente, preta ou de cor escura produzida por vulcanização de borracha natural com uma alta proporção de enxofre, muitas vezes usado para isolamento elétrico, pentes e botões.","example_en":"Early telephone receivers were often made of ebonite for its insulating properties.","example_pt":"Os primeiros receptores telefônicos eram feitos de ebonita por suas propriedades isolantes.","cefr_level":"C1","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"eccentricity","translation":"excentricidade","definition_en":"The quality of being unconventional, odd, or peculiar in behavior or appearance.","definition_pt":"A qualidade de ser não convencional, estranho, ou peculiar em comportamento ou aparência.","example_en":"His eccentricity made him a memorable character in the neighborhood.","example_pt":"Sua excentricidade o tornou um personagem memorável na vizinhança.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"ecclesiastic","translation":"eclesiástico","definition_en":"Of or relating to the Christian Church or its clergy.","definition_pt":"Ou se relacionando com a Igreja Cristã ou seu clero.","example_en":"The ecclesiastic council met to discuss the new doctrine.","example_pt":"O Conselho Eclesiástico se reuniu para discutir a nova doutrina.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"ecclesiology","translation":"eclesiologia","definition_en":"The branch of theology that deals with the nature, structure, and functions of the Christian Church.","definition_pt":"O ramo da teologia que trata da natureza, estrutura e funções da Igreja Cristã.","example_en":"Ecclesiology explores the role of the church in modern society.","example_pt":"A eclesiologia explora o papel da igreja na sociedade moderna.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"echinococcosis","translation":"hidatidose","definition_en":"A serious parasitic disease caused by infection with the larval stage of tapeworms of the genus Echinococcus, leading to cyst formation in organs such as the liver and lungs.","definition_pt":"Uma grave doença parasitária causada por infecção com o estágio larval de ténias do gênero Echinococcus, levando à formação de cisto em órgãos como fígado e pulmões.","example_en":"Echinococcosis is often transmitted through contact with infected dogs or contaminated food.","example_pt":"Equinococose é transmitida por contato com cães infectados ou comida contaminada.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"echinoderm","translation":"equinodermo","definition_en":"A marine invertebrate animal characterized by a five-part radially symmetrical body, tube feet, and a water vascular system.","definition_pt":"Um animal invertebrado marinho caracterizado por um corpo radialmente simétrico de cinco partes, pés de tubo e um sistema vascular de água.","example_en":"Starfish and sea urchins are common examples of echinoderms.","example_pt":"Estrelas do mar e ouriços do mar são exemplos comuns de equinodermos.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"echocardiography","translation":"ecocardiografia","definition_en":"A noninvasive diagnostic procedure that uses ultrasound waves to create images of the heart's structure, movement, and function.","definition_pt":"Um procedimento diagnóstico não invasivo que usa ondas de ultrassom para criar imagens da estrutura, movimento e função do coração.","example_en":"The cardiologist ordered an echocardiography to assess the patient's heart valves.","example_pt":"O cardiologista pediu uma ecocardiografia para avaliar as válvulas cardíacas do paciente.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"echolalia","translation":"ecolalia","definition_en":"The repetition of sounds or words spoken by others, typically observed in infants as part of language development.","definition_pt":"A repetição de sons ou palavras faladas por outros, tipicamente observadas em bebês como parte do desenvolvimento da linguagem.","example_en":"The baby's echolalia was a normal part of learning to speak.","example_pt":"A ecolalia do bebê era uma parte normal de aprender a falar.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"echolocation","translation":"ecolocalização","definition_en":"A biological system used by some animals to determine the location of objects by emitting sound waves and interpreting the returning echoes.","definition_pt":"Um sistema biológico usado por alguns animais para determinar a localização dos objetos, emitindo ondas sonoras e interpretando os ecos retornados.","example_en":"Bats use echolocation to navigate and hunt for insects in complete darkness.","example_pt":"Morcegos usam ecolocalização para navegar e caçar insetos em completa escuridão.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"eclampsia","translation":"eclâmpsia","definition_en":"A serious condition in pregnancy characterized by seizures and high blood pressure, often occurring after preeclampsia.","definition_pt":"Uma grave condição na gravidez caracterizada por convulsões e pressão alta, ocorrendo frequentemente após pré-eclâmpsia.","example_en":"Eclampsia requires immediate medical intervention to protect both mother and baby.","example_pt":"Eclâmpsia requer intervenção médica imediata para proteger a mãe e o bebê.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"eclecticism","translation":"ecletismo","definition_en":"The practice of selecting and combining elements from various doctrines, styles, or systems according to what seems most appropriate, rather than adhering strictly to one.","definition_pt":"A prática de selecionar e combinar elementos de várias doutrinas, estilos ou sistemas de acordo com o que parece mais apropriado, em vez de aderir estritamente a um.","example_en":"His approach to architecture is marked by eclecticism, borrowing elements from Gothic and modern styles.","example_pt":"Sua abordagem à arquitetura é marcada pelo ecletismo, emprestando elementos de estilos góticos e modernos.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"ecliptic","translation":"eclíptica","definition_en":"The great circle on the celestial sphere representing the apparent annual path of the sun; the plane of the Earth's orbit around the sun, making an angle of about 23.5 degrees with the celestial equator.","definition_pt":"O grande círculo na esfera celestial representando o aparente caminho anual do sol, o plano da órbita da Terra em torno do sol, fazendo um ângulo de cerca de 23,5 graus com o equador celestial.","example_en":"The planets are always found near the ecliptic in the night sky.","example_pt":"Os planetas são sempre encontrados perto da eclíptica no céu noturno.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"ecologically","translation":"ecologicamente","definition_en":"In a way that relates to the environment and the relationships between living organisms and their surroundings.","definition_pt":"De uma forma que se relaciona com o meio ambiente e as relações entre organismos vivos e seus arredores.","example_en":"The region is ecologically diverse, with many unique species.","example_pt":"A região é ecologicamente diversa, com muitas espécies únicas.","cefr_level":"B2","word_type":"adverb","category_slug":"science","frequency_rank":null},
{"word":"ecologist","translation":"ecólogo","definition_en":"A biologist who studies the relationships between living organisms and their natural surroundings.","definition_pt":"Um biólogo que estuda as relações entre organismos vivos e seu ambiente natural.","example_en":"The ecologist analyzed the impact of deforestation on local wildlife.","example_pt":"O ecologista analisou o impacto do desmatamento na vida selvagem local.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"econometrics","translation":"econometria","definition_en":"The application of mathematical and statistical methods to analyze and test economic theories using real-world data.","definition_pt":"A aplicação de métodos matemáticos e estatísticos para analisar e testar teorias econômicas usando dados do mundo real.","example_en":"Econometrics is essential for forecasting economic trends.","example_pt":"A econometria é essencial para prever tendências econômicas.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"ecoterrorism","translation":"ecoterrorismo","definition_en":"The use of violent acts or sabotage to further the political or social goals of environmental activists.","definition_pt":"O uso de atos violentos ou sabotagem para promover os objetivos políticos ou sociais de ativistas ambientais.","example_en":"The group was accused of ecoterrorism after setting fire to a logging facility.","example_pt":"O grupo foi acusado de ecoterrorismo depois de incendiar uma instalação madeireira.","cefr_level":"C1","word_type":"noun","category_slug":"politics","frequency_rank":null},
{"word":"ecotourism","translation":"ecoturismo","definition_en":"Travel to natural areas, especially those that are fragile or rare, with the aim of observing wildlife and supporting conservation efforts.","definition_pt":"Viaje para áreas naturais, especialmente aquelas frágeis ou raras, com o objetivo de observar a vida selvagem e apoiar os esforços de conservação.","example_en":"Ecotourism in Costa Rica helps protect its rainforests.","example_pt":"Ecoturismo na Costa Rica ajuda a proteger suas florestas tropicais.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"ectoblast","translation":"ectoblasto","definition_en":"The outermost of the three primary germ layers in an embryo, which develops into the skin, nervous system, and related structures.","definition_pt":"A mais externa das três camadas primárias de germes em um embrião, que se desenvolve na pele, sistema nervoso e estruturas relacionadas.","example_en":"The ectoblast differentiates into the epidermis and neural tissues.","example_pt":"O ectoblasto se diferencia na epiderme e nos tecidos neurais.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"ectoderm","translation":"ectoderme","definition_en":"The outermost of the three primary germ layers in an embryo, developing into the nervous system, skin, and related structures.","definition_pt":"A mais externa das três camadas primárias de germes em um embrião, desenvolvendo-se no sistema nervoso, pele e estruturas relacionadas.","example_en":"The ectoderm differentiates into the epidermis and the neural tube.","example_pt":"O ectoderme se diferencia na epiderme e no tubo neural.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"ectoparasite","translation":"ectoparasita","definition_en":"A parasitic organism that lives on the outside of its host's body, such as fleas, ticks, or lice.","definition_pt":"Um organismo parasita que vive fora do corpo do hospedeiro, como pulgas, carrapatos ou piolhos.","example_en":"Fleas are common ectoparasites that infest dogs and cats.","example_pt":"Fleas são ectoparasitas comuns que infestam cães e gatos.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"ectothermic","translation":"ectotérmico","definition_en":"Describing animals whose body temperature changes with the temperature of their surroundings, such as reptiles, amphibians, and fish.","definition_pt":"Descrevendo animais cuja temperatura corporal muda com a temperatura de seu entorno, como répteis, anfíbios e peixes.","example_en":"Snakes are ectothermic animals that rely on the sun to warm their bodies.","example_pt":"Cobras são animais ectotérmicos que dependem do sol para aquecer seus corpos.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"ecuadorian","translation":"equatoriano","definition_en":"Of or pertaining to Ecuador, its people, or its culture.","definition_pt":"Ou pertencente ao Equador, ao seu povo, ou à sua cultura.","example_en":"She loves Ecuadorian cuisine, especially ceviche.","example_pt":"Ela adora cozinha equatoriana, especialmente ceviche.","cefr_level":"A2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"ecumenical","translation":"ecumênico","definition_en":"Relating to or representing the whole Christian Church, or promoting unity among different Christian denominations.","definition_pt":"Relacionando ou representando toda a Igreja Cristã, ou promovendo a união entre diferentes denominações cristãs.","example_en":"The ecumenical council aimed to bridge differences between the churches.","example_pt":"O conselho ecumênico visava a ponte entre as diferenças entre as igrejas.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"ecumenism","translation":"ecumenismo","definition_en":"A movement that encourages cooperation and unity among different religious groups, especially Christian denominations.","definition_pt":"Um movimento que incentiva a cooperação e a união entre diferentes grupos religiosos, especialmente denominações cristãs.","example_en":"The conference focused on ecumenism and interfaith dialogue.","example_pt":"A conferência se concentrou no ecumenismo e no diálogo inter-religioso.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"edification","translation":"edificação","definition_en":"The instruction or improvement of a person morally or intellectually.","definition_pt":"A instrução ou melhoria de uma pessoa moral ou intelectualmente.","example_en":"The lecture was intended for the edification of the students.","example_pt":"A palestra foi destinada à edificação dos alunos.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"educatee","translation":"educando","definition_en":"A person who is receiving instruction or training at a school, college, or other educational establishment.","definition_pt":"Uma pessoa que está recebendo instrução ou treinamento em uma escola, faculdade ou outro estabelecimento educacional.","example_en":"The educatee submitted the assignment on time.","example_pt":"O educador apresentou a tarefa na hora.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"eelgrass","translation":"zostera","definition_en":"A submerged marine plant with very long, narrow leaves, found abundantly along North Atlantic coasts.","definition_pt":"Uma planta marinha submersa com folhas muito longas e estreitas, encontradas abundantemente ao longo das costas do Atlântico Norte.","example_en":"Eelgrass provides important habitat for marine life.","example_pt":"Eelgrass fornece habitat importante para a vida marinha.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"effectivity","translation":"efetividade","definition_en":"The capacity or power to be effective; the quality of being able to bring about a desired effect or outcome.","definition_pt":"A capacidade ou poder para ser eficaz, a qualidade de ser capaz de produzir um efeito ou resultado desejado.","example_en":"The effectivity of the new policy was measured by the increase in productivity.","example_pt":"A efetividade da nova política foi medida pelo aumento da produtividade.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"efferent","translation":"eferente","definition_en":"Relating to nerves or nerve impulses that carry signals away from the central nervous system to muscles or glands.","definition_pt":"Relacionado com nervos ou impulsos nervosos que levam sinais do sistema nervoso central para músculos ou glândulas.","example_en":"Efferent neurons transmit motor commands from the brain to the limbs.","example_pt":"Os neurônios eferentes transmitem comandos motores do cérebro para os membros.","cefr_level":"C2","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"effervescence","translation":"efervescência","definition_en":"The escape of gas from a liquid, resulting in bubbles or foam.","definition_pt":"A fuga de gás de um líquido, resultando em bolhas ou espuma.","example_en":"The effervescence of the soda made it refreshing.","example_pt":"A efervescência do refrigerante o refrescou.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"efficaciously","translation":"eficazmente","definition_en":"In a manner that produces the desired result or effect; efficiently.","definition_pt":"De uma forma que produz o resultado ou efeito desejado, eficientemente.","example_en":"The new drug works efficaciously against the virus.","example_pt":"A nova droga funciona eficientemente contra o vírus.","cefr_level":"C2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"effrontery","translation":"descaramento","definition_en":"Shameless or rude boldness; audacity.","definition_pt":"Desavergonhada ou rude ousadia, audácia.","example_en":"He had the effrontery to ask for a raise after only a week on the job.","example_pt":"Ele teve a espora para pedir um aumento depois de apenas uma semana no trabalho.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"effusive","translation":"efusivo","definition_en":"Showing or expressing feelings, gratitude, or praise in an unrestrained or heartfelt manner.","definition_pt":"Mostrando ou expressando sentimentos, gratidão, ou louvor de uma forma irrestrita ou sincera.","example_en":"She was effusive in her thanks for the generous gift.","example_pt":"Ela foi efusiva em seu agradecimento pelo presente generoso.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"effusively","translation":"efusivamente","definition_en":"In a manner that shows strong, often exaggerated, feelings of enthusiasm, gratitude, or affection.","definition_pt":"De uma forma que mostra forte, muitas vezes exagerada, sentimentos de entusiasmo, gratidão, ou afeição.","example_en":"She thanked the audience effusively after her performance.","example_pt":"Ela agradeceu ao público efusivamente após sua performance.","cefr_level":"C1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"effusiveness","translation":"efusividade","definition_en":"The quality of showing strong, unrestrained emotion or enthusiasm in a friendly and talkative manner.","definition_pt":"A qualidade de mostrar emoção forte, sem restrições ou entusiasmo de uma forma amigável e falante.","example_en":"Her effusiveness made everyone feel welcome at the party.","example_pt":"Sua efusividade fez todos se sentirem bem-vindos na festa.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"egalitarian","translation":"igualitário","definition_en":"Relating to or believing in the principle that all people are equal and deserve equal rights and opportunities.","definition_pt":"Relacionando-se ou acreditando no princípio de que todas as pessoas são iguais e merecem direitos e oportunidades iguais.","example_en":"The organization promotes an egalitarian society.","example_pt":"A organização promove uma sociedade igualitária.","cefr_level":"C2","word_type":"adjective","category_slug":"politics","frequency_rank":null},
{"word":"egalitarianism","translation":"igualitarismo","definition_en":"The belief that all people are equal and deserve equal rights, opportunities, and treatment in society.","definition_pt":"A crença de que todas as pessoas são iguais e merecem direitos, oportunidades e tratamento iguais na sociedade.","example_en":"Egalitarianism is a core principle of many democratic societies.","example_pt":"O igualitarismo é um princípio fundamental de muitas sociedades democráticas.","cefr_level":"C1","word_type":"noun","category_slug":"politics","frequency_rank":null},
{"word":"eggbeater","translation":"batedeira","definition_en":"A hand‑held or electric device used for beating eggs, whipping cream, or mixing light batters.","definition_pt":"Um dispositivo portátil ou elétrico usado para bater ovos, chicotear creme, ou misturar massa leve.","example_en":"She used an eggbeater to prepare the meringue.","example_pt":"Ela usou um batedor de ovos para preparar o merengue.","cefr_level":"A2","word_type":"noun","category_slug":"food","frequency_rank":null},
{"word":"egocentrism","translation":"egocentrismo","definition_en":"The characteristic of being excessively preoccupied with one's own needs, interests, and perspective, often with a lack of consideration for others.","definition_pt":"A característica de estar excessivamente preocupado com as próprias necessidades, interesses e perspectiva, muitas vezes com falta de consideração pelos outros.","example_en":"His egocentrism made it hard for him to maintain close friendships.","example_pt":"Seu egocentrismo dificultava a manutenção de amizades íntimas.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"egoism","translation":"egoísmo","definition_en":"The moral theory that one's own self-interest is the foundation of morality and that actions are morally right if they benefit oneself.","definition_pt":"A teoria moral de que o próprio interesse é a base da moralidade e que as ações são moralmente corretas se elas se beneficiam.","example_en":"Ethical egoism argues that individuals should always act in their own best interest.","example_pt":"O egoísmo ético argumenta que os indivíduos devem sempre agir em seu próprio interesse.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"egomania","translation":"egomania","definition_en":"An intense and overwhelming preoccupation with oneself, one's own needs, and desires, often to the exclusion of others.","definition_pt":"Uma intensa e esmagadora preocupação consigo mesmo, com suas próprias necessidades e desejos, muitas vezes à exclusão dos outros.","example_en":"His egomania made it impossible for him to work in a team.","example_pt":"Sua egomania tornou impossível para ele trabalhar em uma equipe.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"egret","translation":"garça","definition_en":"A type of heron, typically white, known for its long, delicate feathers that grow during the breeding season.","definition_pt":"Um tipo de garça, tipicamente branca, conhecida por suas penas longas e delicadas que crescem durante a época de reprodução.","example_en":"An egret stood motionless in the shallow water, waiting for fish.","example_pt":"Um egret ficou imóvel na água rasa, esperando por peixes.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"eider","translation":"êider","definition_en":"A large sea duck of the genus Somateria, found in northern regions, known for its soft down feathers.","definition_pt":"Um grande pato marinho do gênero Somateria, encontrado nas regiões do norte, conhecido por suas penas macias.","example_en":"Eiders are commonly found along the coasts of Scandinavia.","example_pt":"Os esiders são comumente encontrados ao longo das costas da Escandinávia.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"eiderdown","translation":"edredom","definition_en":"A warm, soft quilt or duvet, traditionally filled with the soft feathers (down) of the eider duck.","definition_pt":"Uma colcha ou edredão quente e macia, tradicionalmente cheia de penas macias (para baixo) do pato eider.","example_en":"She snuggled under the warm eiderdown on the cold winter night.","example_pt":"Ela se aconchegou sob o eiderdown quente na noite fria de inverno.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"eidetic","translation":"eidético","definition_en":"Relating to the ability to recall visual images with exceptional clarity and detail, almost like a photograph.","definition_pt":"Relacionado à capacidade de lembrar imagens visuais com excepcional clareza e detalhe, quase como uma fotografia.","example_en":"She has an eidetic memory and can recall entire pages of a book.","example_pt":"Ela tem uma memória eidética e pode lembrar páginas inteiras de um livro.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"eigenvalue","translation":"autovalor","definition_en":"A scalar associated with a linear transformation of a vector space, such that there exists a non-zero vector whose direction is unchanged by the transformation.","definition_pt":"Um escalar associado a uma transformação linear de um espaço vetorial, de tal forma que existe um vetor não-zero cuja direção é inalterada pela transformação.","example_en":"The eigenvalues of the matrix were calculated to determine stability.","example_pt":"Os autovalores da matriz foram calculados para determinar estabilidade.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"eightieth","translation":"octogésimo","definition_en":"Being the number 80 in a sequence; the ordinal form of eighty.","definition_pt":"Sendo o número 80 em uma sequência, a forma ordinal de oitenta.","example_en":"She celebrated her eightieth birthday with a big party.","example_pt":"Ela celebrou seu 80o aniversário com uma grande festa.","cefr_level":"A2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
